package main

import (
	"encoding/json"
	"fmt"
)

type User struct {
	Name  string `json:"name"`
	Email string `json:"email,omitempty"`
}

func main() {
	out, _ := json.Marshal(User{Name: "Ada"})
	fmt.Println(string(out))
	var u User
	json.Unmarshal([]byte(`{"name":"Linus","email":"l@x.org"}`), &u)
	fmt.Println(u.Email)
}
